@IsTest static void escalateSetsPriorityAndOwner() {
    Case c = new Case(Subject = 'Fabrikam outage', Priority = 'Low');
    insert c;
    CaseService.escalate(c.Id);
    Case r = [SELECT Priority, OwnerId FROM Case WHERE Id = :c.Id];
    Assert.areEqual('High', r.Priority);
    Assert.areEqual(supportQueueId(), r.OwnerId);
}

