@IsTest static void closingACase() {
    Case c = new Case(Subject = 'Contoso login', Status = 'New');
    insert c;
    c.Status = 'Closed';
    update c;
    Case r = [SELECT Status FROM Case WHERE Id = :c.Id];
    Assert.areEqual('Closed', r.Status);
}

test('blank name is refused locally', async () => {
  const api = { save: jest.fn() };
  const form = mountForm({ api });
  form.setName('   ');
  await form.submit();
  expect(form.error()).toBe('Name is required');
  expect(api.save).not.toHaveBeenCalled();
});

